import{_ as p,a0 as r,w as u,s,I as t,x as n,a1 as i,A as l,ao as g}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150612 Linux_Logo--A Command Line Tool to Print Color ANSI Logos of Linux Distributions","title":"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具","tag":"201507","desc":""},"relativePath":"201507/20150612 Linux_Logo--A Command Line Tool to Print Color ANSI Logos of Linux Distributions.md","filePath":"[post].md"}'),x={name:"201507/20150612 Linux_Logo--A Command Line Tool to Print Color ANSI Logos of Linux Distributions.md"};function d(L,o,m,a,c,w){const e=r("Link");return u(),s("div",null,[o[17]||(o[17]=t("h1",{id:"linux-logo-–-输出彩色-ansi-linux-发行版徽标的命令行工具",tabindex:"-1"},[n("Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具 "),t("a",{class:"header-anchor",href:"#linux-logo-–-输出彩色-ansi-linux-发行版徽标的命令行工具","aria-label":"Permalink to “Linux_Logo – 输出彩色 ANSI Linux 发行版徽标的命令行工具”"},"​")],-1)),o[18]||(o[18]=t("p",null,"linuxlogo（或叫 linux_logo）是一款在Linux命令行下用彩色 ANSI 代码生成附带有系统信息的发行版徽标的工具。",-1)),o[19]||(o[19]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/06/Linux_Logo.png",alt:"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标"})],-1)),o[20]||(o[20]=t("p",null,[t("em",null,"Linux_Logo – 输出彩色 ANSI Linux 发行版徽标")],-1)),o[21]||(o[21]=t("p",null,"这个小工具可以从 /proc 文件系统中获取系统信息并可以显示包括主机上安装的发行版在内的很多发行版的徽标。",-1)),o[22]||(o[22]=t("p",null,"与徽标一同显示的系统信息包括 ： Linux 内核版本，最近一次编译Linux内核的时间，处理器/核心数量，速度，制造商，以及哪一代处理器。它还能显示总共的物理内存大小。",-1)),o[23]||(o[23]=t("p",null,"无独有偶，screenfetch是一个拥有类似功能的工具，它也能显示发行版徽标，同时还提供更加详细美观的系统信息。我们之前已经介绍过这个工具，你可以参考一下链接：",-1)),t("ul",null,[t("li",null,[i(e,{href:"https://linux.cn/article-1947-1.html"},{default:l(()=>[...o[0]||(o[0]=[n("screenFetch: 命令行信息截图工具",-1)])]),_:1})])]),o[24]||(o[24]=t("p",null,"linux_logo 和 Screenfetch 并完全一样。尽管 screenfetch 的输出较为整洁并提供更多细节， 但 linux_logo 则提供了更多的彩色 ANSI 图标， 并且提供了格式化输出的选项。",-1)),t("p",null,[o[2]||(o[2]=n("linux_logo 主要使用C语言编写并将 linux 徽标呈现在 X 窗口系统中因此需要安装图形界面 X11 或 X 系统（LCTT 译注：此处应是错误的。按说不需要任何图形界面支持，并且译者从其官方站 ",-1)),i(e,{href:"http://www.deater.net/weave/vmwprod/linux_logo"},{default:l(()=>[...o[1]||(o[1]=[n("http://www.deater.net/weave/vmwprod/linux_logo",-1)])]),_:1}),o[3]||(o[3]=n(" 也没找到任何相关 X11的信息）。这个软件使用GNU 2.0协议。",-1))]),o[25]||(o[25]=g(`<p>本文中，我们将使用以下环境测试 linux_logo 工具。</p><pre><code>操作系统 : Debian Jessie
处理器 : i3 / x86_64
</code></pre><h3 id="在-linux-中安装-linux-logo工具" tabindex="-1">在 Linux 中安装 Linux Logo工具 <a class="header-anchor" href="#在-linux-中安装-linux-logo工具" aria-label="Permalink to “在 Linux 中安装 Linux Logo工具”">​</a></h3><p><strong>1. linuxlogo软件包 ( 5.11 稳定版) 可通过如下方式使用 apt, yum 或 dnf 在所有发行版中使用默认的软件仓库进行安装</strong></p><pre><code># apt-get install linux_logo			[用于基于 Apt 的系统] （译者注：Ubuntu中，该软件包名为linuxlogo）
# yum install linux_logo			[用于基于 Yum 的系统]
# dnf install linux_logo			[用于基于 Dnf 的系统]
或
# dnf install linux_logo.x86_64			[用于 64 位系统]
</code></pre><p><strong>2. 装好linuxlogo软件包之后，你可以使用命令 <code>linuxlogo</code> 来获取你当前使用的发行版的默认徽标..</strong></p><pre><code># linux_logo
或
# linuxlogo
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Get-Default-OS-Logo.png" alt="获取默认系统徽标"></p><p><em>获取默认系统徽标</em></p><p><strong>3. 使用 <code>[-a]</code> 选项可以输出没有颜色的徽标。当在黑白终端里使用 linux_logo 时，这个选项会很有用。</strong></p><pre><code># linux_logo -a
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Black-and-White-Linux-Logo.png" alt="黑白 Linux 徽标"></p><p><em>黑白 Linux 徽标</em></p><p><strong>4. 使用 <code>[-l]</code> 选项可以仅输出徽标而不包含系统信息。</strong></p><pre><code># linux_logo -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-Distribution-Logo.png" alt="输出发行版徽标"></p><p><em>输出发行版徽标</em></p><p><strong>5. <code>[-u]</code> 选项可以显示系统运行时间。</strong></p><pre><code># linux_logo -u
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-System-Uptime.png" alt="输出系统运行时间"></p><p><em>输出系统运行时间</em></p><p><strong>6. 如果你对系统平均负载感兴趣，可以使用 <code>[-y]</code> 选项。你可以同时使用多个选项。</strong></p><pre><code># linux_logo -y
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-System-Load-Average.png" alt="输出系统平均负载"></p><p><em>输出系统平均负载</em></p><p>如需查看更多选项并获取相关帮助，你可以使用如下命令。</p><pre><code># linux_logo -h
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/linuxlogo-options.png" alt="Linuxlogo 选项及帮助"></p><p><em>Linuxlogo选项及帮助</em></p><p><strong>7. 此工具内置了很多不同发行版的徽标。你可以使用 <code>[-L list]</code> 选项查看在这些徽标的列表。</strong></p><pre><code># linux_logo -L list
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/List-of-Linux-Logos.png" alt="Linux 徽标列表"></p><p><em>Linux 徽标列表</em></p><p>如果你想输出这个列表中的任意徽标，可以使用 <code>-L NUM</code> 或 <code>-L NAME</code> 来显示想要选中的图标。</p><ul><li>-L NUM – 会输出列表中序号为 NUM 的图标 (不推荐).</li><li>-L NAME – 会输出列表中名为 NAME 的图标。</li></ul><p>例如，如果想要显示 AIX 的徽标，你可以使用如下命令</p><pre><code># linux_logo -L 1
或
# linux_logo -L aix
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-AIX-Logo.png" alt="输出 AIX 图标"></p><p><em>输出 AIX 图标</em></p><p><strong>注</strong>: 命令中的使用 <code>-L 1</code> 是因为 AIX 徽标在列表中的编号是1，而使用 <code>-L aix</code> 则是因为 AIX 徽标在列表中的名称为 aix</p><p>同样的，你还可以使用这些选项输出任何图标，以下是一些例子..</p><pre><code># linux_logo -L 27
# linux_logo -L 21
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Various-Linux-Logos.png" alt="各种 Linux 徽标"></p><p><em>各种 Linux 徽标</em></p><p>你可以通过徽标对应的编号或名字使用任意徽标。</p><h3 id="一些使用-linux-logo-的建议和提示" tabindex="-1">一些使用 Linux_logo 的建议和提示### <a class="header-anchor" href="#一些使用-linux-logo-的建议和提示" aria-label="Permalink to “一些使用 Linux_logo 的建议和提示###”">​</a></h3><p><strong>8. 你可以在登录界面输出你的 Linux 发行版徽标。要输出默认徽标，你可以在 <code> ~/.bashrc</code> 文件的最后添加以下内容。</strong></p><pre><code>if [ -f /usr/bin/linux_logo ]; then linux_logo; fi
</code></pre><p><strong>注</strong>: 如没有<code> ~/.bashrc</code> 文件，你需要在当前用户的 home 目录下新建一个。</p><p><strong>9. 在添加以上内容后，你只需要注销并重新登录即可看到你的发行版的默认徽标</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-Logo-on-Login.png" alt="Print Logo on User Login"></p><p><em>在用户登录时输出徽标</em></p><p>其实你也可以在登录后输出任意图标，只需加入以下内容：</p><pre><code>if [ -f /usr/bin/linux_logo ]; then linux_logo -L num; fi
</code></pre><p><strong>重要</strong>: 不要忘了将 num 替换成你想使用的图标。</p><p><strong>10. 你也能直接指定徽标所在的位置来显示你自己的徽标。</strong></p><pre><code># linux_logo -D /path/to/ASCII/logo
</code></pre><p><strong>11. 在远程登录时输出图标。</strong></p><pre><code># /usr/local/bin/linux_logo &gt; /etc/issue.net
</code></pre><p>如果你想使用　ASCII　徽标而不是含有颜色的 ANSI 徽标，则使用如下命令</p><pre><code># /usr/local/bin/linux_logo -a &gt; /etc/issue.net
</code></pre><p><strong>12. 创建一个 Linux 上的端口 - 用于回应连接的端口。要创建 Linux 端口， 则需在 /etc/services 文件中加入以下内容</strong></p><pre><code>penguin	4444/tcp	penguin
</code></pre><p>这里的 <code>4444</code> 是一个未被任何其他资源使用的空闲端口。你也可以使用其他端口。你还需要在 /etc/inetd.conf中加入以下内容：</p><pre><code>penguin	stream	     tcp	nowait	root /usr/local/bin/linux_logo 
</code></pre><p>并使用以下命令重启 inetd 服务</p><pre><code># killall -HUP inetd
</code></pre><p>（LCTT 译注：然后你就可以远程或本地连接到这个端口，并显示这个徽标了。）</p><p>linux_logo 还可以用做启动脚本来愚弄攻击者或对你朋友使用恶作剧。这是一个我经常在我的脚本中用来获取不同发行版输出的好工具。</p><p>试过一次后，你就不会忘记的。让我们知道你对这个工具的想法及它对你的作用吧。 不要忘记给评论、点赞或分享！</p><hr>`,71)),t("p",null,[o[5]||(o[5]=n("via: ",-1)),i(e,{href:"http://www.tecmint.com/linux_logo-tool-to-print-color-ansi-logos-of-linux/"},{default:l(()=>[...o[4]||(o[4]=[n("http://www.tecmint.com/linux_logo-tool-to-print-color-ansi-logos-of-linux/",-1)])]),_:1})]),t("p",null,[o[9]||(o[9]=n("作者：",-1)),i(e,{href:"http://www.tecmint.com/author/avishek/"},{default:l(()=>[...o[6]||(o[6]=[n("Avishek Kumar",-1)])]),_:1}),o[10]||(o[10]=n(" 译者：",-1)),i(e,{href:"https://github.com/KevinSJ"},{default:l(()=>[...o[7]||(o[7]=[n("KevinSJ",-1)])]),_:1}),o[11]||(o[11]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...o[8]||(o[8]=[n("wxy",-1)])]),_:1})]),t("p",null,[o[14]||(o[14]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[12]||(o[12]=[n("LCTT",-1)])]),_:1}),o[15]||(o[15]=n(" 原创翻译，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...o[13]||(o[13]=[n("Linux中国",-1)])]),_:1}),o[16]||(o[16]=n(" 荣誉推出",-1))])])}const T=p(x,[["render",d]]);export{A as __pageData,T as default};
